package com.gymmind.nutrition.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.member.domain.repository.MemberRepository; import com.gymmind.nutrition.domain.model.NutritionRecord; import com.gymmind.nutrition.domain.repository.NutritionRecordRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map;
@Service public class DefaultNutritionRecordService implements NutritionRecordService { final NutritionRecordRepository records; final MemberRepository members; final AuditRecorder audit; public DefaultNutritionRecordService(NutritionRecordRepository r,MemberRepository m,AuditRecorder a){records=r;members=m;audit=a;} @Transactional public NutritionRecordView create(CurrentActor actor,CreateNutritionRecordCommand c){if(actor==null||actor.tenantId()==null||!actor.roles().contains(RoleCode.MEMBER)||!actor.hasPermission("nutrition:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!actor.tenantId().equals(c.tenantId())||c.recordDate()==null||c.calories()<0||c.protein()<0||c.carbohydrate()<0||c.fat()<0||c.notes()==null||c.notes().isBlank())throw new BusinessException(ErrorCode.VALIDATION_FAILED);Long memberId=members.findByTenantIdAndUserId(actor.tenantId(),actor.userId()).map(com.gymmind.member.domain.model.Member::getId).orElseThrow(()->new BusinessException(ErrorCode.RESOURCE_NOT_FOUND));NutritionRecord r=records.save(NutritionRecord.create(actor.tenantId(),memberId,c.recordDate(),c.calories(),c.protein(),c.carbohydrate(),c.fat(),c.notes()));audit.record(new AuditEvent("NUTRITION_RECORD_CREATED","NUTRITION_RECORD",r.getId(),AuditResult.SUCCESS,"nutrition-record-service",Map.of("resourceName","nutrition-record")));return NutritionRecordView.from(r);} }
